import type { ChallengeTheme, Criterion, MetricField, PbKey, ToolId } from '../domain/types';
import type { LibraryItem } from './challenges';

/**
 * The wider challenge library: everyday skills anyone can attempt in a day, rated 1 (gentle)
 * to 5 (demanding). The plan generator picks from these plus the Signature 30.
 * Keep entries universal — no country-, person- or brand-specific content.
 */

interface Opts {
  bonus?: string;
  equipment?: string[];
  safety?: string[];
  metrics?: MetricField[];
  criteria?: Criterion[];
  pbKeys?: PbKey[];
  tools?: ToolId[];
  evidence?: false | string;
}

function x(id: string, title: string, theme: ChallengeTheme, category: string, difficulty: number, estimatedMinutes: number, objective: string, description: string, preparation: string[], learningPlan: string[], o: Opts = {}): LibraryItem {
  return {
    id,
    title,
    theme,
    category,
    difficulty,
    estimatedMinutes,
    objective,
    description,
    preparation,
    learningPlan,
    bonus: o.bonus ?? null,
    equipment: o.equipment ?? [],
    safety: o.safety ?? [],
    metrics: o.metrics ?? [],
    criteria: o.criteria ?? [{ id: 'main', label: objective }],
    pbKeys: o.pbKeys ?? [],
    tools: o.tools ?? [],
    stretchGoal: null,
    evidence: o.evidence === false ? { enabled: false, accept: '', label: '' } : { enabled: true, accept: o.evidence ?? 'image/*,video/*,audio/*', label: 'Evidence (optional)' },
  };
}

/** A single number that must reach `value`; logged attempts track the personal best. */
function atLeast(key: string, label: string, value: number, unit?: string): Opts {
  return {
    metrics: [{ key, label, type: 'number', min: 0, ...(unit ? { unit } : {}) }],
    criteria: [{ id: 'main', label: `${label}: ${value}${unit ? ` ${unit}` : ''}`, rule: { op: 'gte', key, value } }],
    pbKeys: [{ key, label, better: 'higher', ...(unit ? { unit } : {}) }],
  };
}

/** Before/after measurement that must improve by `pct` percent. */
function improve(label: string, pct: number, unit: string, better: 'higher' | 'lower' = 'higher'): Opts {
  return {
    metrics: [
      { key: 'baseline', label: `Starting ${label.toLowerCase()}`, type: 'number', min: 0, unit, group: 'Baseline' },
      { key: 'final', label: `Final ${label.toLowerCase()}`, type: 'number', min: 0, unit, group: 'Final' },
    ],
    criteria: [{ id: 'main', label: `${label} improved by ${pct}%`, rule: { op: 'improve', baseline: 'baseline', final: 'final', pct, better } }],
    pbKeys: [{ key: 'final', baselineKey: 'baseline', label, better, unit }],
    tools: ['pbCalc'],
  };
}

